"""Explain interval validation, touching boundaries, first merge and init data."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1849': ('주소 0을 쓰면 안 되는지는 컴퓨터 종류의 규칙도 살펴야 해요. 또 경고 표시가 있다고 잘못된 입력이 자동으로 고쳐지는 것은 아니에요.', '구간 검사 조건과 기종별 예외, 경고의 한계를 이해합니다.', 'start 0·end 4096을 쓰고 s390 설정 켜짐과 꺼짐 두 경우를 비교하세요. 이는 조건을 읽는 종이 예시예요.', ['구간 기록 함수는 시작 주소 start와 끝 경계 end를 받아요. 시작은 끝보다 작아야 해요. start >= end는 시작이 끝과 같거나 더 크다는 뜻이고 이런 경우 경고 조건에 걸려요.', 'end가 0인 경우도 경고해요. start가 0인 경우는 조건이 하나 더 있어요. !IS_ENABLED(CONFIG_S390) && !nstart는 s390 설정이 꺼져 있고 시작 주소가 0일 때라는 뜻이에요. &&는 둘 다 맞아야 한다는 표시예요.', 's390은 Linux가 지원하는 컴퓨터 구조의 한 종류예요. 원문 주석은 이 구조에서는 가상 주소 0이 유효하다고 설명해요. 가상 주소는 프로그램이나 커널이 메모리를 가리킬 때 쓰는 주소 체계예요. 그래서 모든 기종의 주소 0을 같은 규칙으로 취급하지 않아요.', '종이 예에서 start 0, end 4096이고 s390 설정이 켜져 있으면 시작 0 조건만으로는 경고하지 않아요. 설정이 꺼져 있으면 그 조건에 걸려요. 예외가 있다고 끝 0이나 뒤집힌 구간까지 허용되는 것은 아니에요.', '함수는 배열 사용 개수 future_index가 용량 128과 같은지도 경고해요. 하지만 이 경고 뒤에 잘못된 입력을 고치거나 새 항목 추가를 취소하는 return은 없어요. 실행이 계속되면 뒤의 처리로 진행하므로 호출하는 쪽이 유효한 구간과 용량을 지켜야 해요.', 'KMSAN_WARN_ON은 조건이 참일 때 검사를 끄고 설정에 따라 BUG 처리로 정상 실행이 중단될 수도 있어요. 따라서 단순한 경고 출력만으로 설명해서도 안 돼요. 여기서 중요한 점은 경고가 안전한 입력 보정이나 배열 용량 확장을 해 주지 않는다는 것이에요.'], [('start 0, end 4096이고 s390 설정이 켜져 있으면 시작 0이라는 이유만으로 경고하나요?', ['네. 모든 기종에 같은 시작 0 금지 조건을 적용해요', '아니요. 원문에는 s390 예외가 있어요'], '정답은 두 번째예요. 시작 0 검사에는 s390이 아니라는 조건도 필요해요. 다른 구간 오류까지 허용한다는 뜻은 아니므로 끝과 순서 조건은 별도로 보세요.'), ('용량 경고가 새 항목 추가를 안전하게 취소하는 return 역할도 하나요?', ['아니요. 함수에 그런 반환 분기는 없어요', '네. 경고만 있으면 언제나 배열 밖 쓰기를 안전하게 막아요'], '정답은 첫 번째예요. 경고 뒤 실행이 계속되면 후속 코드로 가요. 설정에 따라 실행이 중단될 수는 있지만 이를 정상적인 용량 검사 후 거부 처리와 같다고 볼 수 없어요.')]), 'os1850': ('두 색칠 구간 사이에 빈칸이 없다면 하나의 긴 구간으로 적을 수 있어요. 이 코드는 겹친 구간뿐 아니라 끝과 시작이 맞닿은 구간도 합쳐요.', '엄격한 비교와 맞닿은 구간 병합, 최소·최대 경계 계산을 이해합니다.', '페이지 번호로 [1,2)와 [2,3)을 그리고 [1,3)으로 합치세요. 끝 번호는 포함하지 않아요.', ['구간은 [start, end)로 적어요. 시작은 포함하고 끝은 제외한다는 뜻이에요. 아래 숫자 예는 주소를 페이지 경계에 맞춘 뒤 페이지 번호로 나타낸 모형이에요.', '기존 구간이 새 구간보다 완전히 앞이나 뒤에 떨어져 있으면 continue로 다음 항목을 살펴요. 비교에 <와 >를 써서 더 작거나 더 큰지를 확인해요. <=나 >=처럼 같은 경우까지 포함하는 비교가 아니에요.', '기존 구간 [1,2)와 새 구간 [2,3)은 실제 칸이 겹치지는 않지만 경계 2에서 맞닿아요. 기존 끝 2가 새 시작 2보다 작지는 않으므로 떨어진 구간으로 건너뛰지 않고 병합해요.', '병합할 시작은 두 시작 중 작은 값 min, 끝은 두 끝 중 큰 값 max예요. [1,2)와 [2,3)은 시작 min(1,2)=1, 끝 max(2,3)=3이 되어 [1,3)으로 적어요.', '겹치는 [1,4)와 [3,5)도 [1,5)로 합칠 수 있어요. 반면 [1,2)와 [3,4)은 사이 [2,3)에 빈 구간이 있으므로 떨어진 것으로 보고 건너뛰어요. 단순히 두 길이를 더하는 것과는 달라요.', '이 작업은 목록의 시작·끝 숫자를 갱신하는 일이에요. 실제 메모리 내용을 옮겨 붙이거나 새 데이터를 쓰는 작업이 아니에요. 기록 구간의 병합과 데이터 복사를 구별하세요.'], [('기존 끝과 새 시작이 같으면 이 구현은 병합하나요?', ['아니요. 반드시 실제 바이트가 겹쳐야 해요', '네. 경계가 맞닿은 구간도 병합해요'], '정답은 두 번째예요. 떨어짐 검사에 엄격한 <와 >를 쓰므로 같은 경계는 그 조건에 들지 않아요. 반열린 구간의 내용이 안 겹쳐도 빈틈 없이 이어지면 합쳐요.'), ('병합한 구간의 시작과 끝은 어떻게 정하나요?', ['시작은 작은 값, 끝은 큰 값을 골라요', '두 길이만 더해서 아무 주소에 붙여요'], '정답은 첫 번째예요. min과 max로 기존 위치를 모두 포함하는 바깥 경계를 구해요. 길이만 더하면 겹친 부분을 두 번 셀 수 있고 실제 위치 정보도 잃어요.')]), 'os1851': ('목록에서 처음 만난 구간만 고친 뒤 연필을 내려놓는다고 생각해 봐요. 뒤의 구간까지 모두 정리하는 작업은 자동으로 따라오지 않아요.', '첫 병합 뒤 종료하는 구현과 전체 구간 정리의 차이를 이해합니다.', '페이지 번호 목록 [1,2), [3,4)에 [2,3)을 넣으세요. 첫 항목만 [1,3)으로 바꾸고 두 번째를 그대로 남기세요.', ['함수는 기존 구간을 앞에서부터 훑어요. 합칠 항목을 찾으면 그 항목의 시작을 min으로, 끝을 max로 바꿔요. 그다음 merged를 true로 설정해 합쳤다는 사실을 기록해요.', '바로 뒤의 break는 for 반복을 끝내요. 따라서 첫 병합 뒤에는 뒤쪽 항목들을 계속 살펴보지 않아요. 반복 밖에서는 merged가 참인지 보고 return으로 함수에서도 돌아가요.', '페이지 번호 모형에서 기존 목록이 [1,2), [3,4)이고 새 구간이 [2,3)이라고 해 봐요. 새 구간은 양쪽 사이를 연결하지만 먼저 만나는 것은 [1,2)이에요.', '첫 항목은 [1,3)으로 바뀌고 거기서 멈춰요. 두 번째 [3,4)는 그대로 남아요. 결과 목록은 [1,3), [3,4)의 두 항목이에요. 이 호출이 자동으로 [1,4) 한 항목을 만들지는 않아요.', '이제 두 구간이 맞닿아 있어도 다시 처음부터 훑는 코드가 없어요. 전체 정리를 하려면 추가 순회나 항목 삭제 같은 작업이 필요하지만 이 본문은 그런 작업을 하지 않아요.', '따라서 병합이라는 말만 보고 언제나 서로 겹치거나 맞닿지 않는 깔끔한 목록을 만든다고 생각하면 안 돼요. 숫자 예를 실제 대입→break→return 순서로 따라가면 함수가 보장하는 범위를 알 수 있어요.'], [('첫 항목과 병합한 뒤 목록 전체를 다시 훑나요?', ['네. 연결된 모든 구간이 하나가 될 때까지 반복해요', '아니요. break로 탐색 반복을 끝내요'], '정답은 두 번째예요. merged=true 다음에 break가 있어요. 반복 밖에서도 병합했으면 return하므로 자동 재탐색이 없어요.'), ('새 구간이 두 기존 구간의 사이를 잇는다면 목록은 반드시 한 항목이 되나요?', ['아니요. 첫 항목만 늘어나고 두 번째가 남을 수 있어요', '네. 어떤 경우에도 한 항목으로 줄어요'], '정답은 첫 번째예요. 예시에서는 [1,3)과 [3,4)가 남아요. 내용 전체를 한 구간으로 표현할 수 있다는 사실과 이 함수가 실제로 그렇게 정리한다는 주장은 달라요.')]), 'os1852': ('목록의 빈 다음 줄에 새 구간을 적고 사용한 줄 수를 하나 늘려요. 이미 있는 줄에 합쳤다면 줄 수를 늘릴 필요가 없어요.', '배열 뒤에 추가하는 순서와 초기화용 데이터의 수명을 이해합니다.', '사용 개수 2인 목록에 새 항목을 추가하면 2번 칸에 적고 개수가 3이 되는 모습을 그리세요.', ['future_index는 현재 구간 항목 수예요. 배열 번호는 0부터 시작하므로 항목이 두 개면 사용 중인 칸은 0번과 1번이고, 다음 빈 칸의 번호는 2예요. 이때 future_index도 2예요.', '기존 구간에 병합했다면 if (merged) return으로 돌아가요. 기존 칸의 경계만 바꾸었기 때문에 새 칸을 추가하거나 사용 개수를 늘리지 않아요.', '병합하지 못했다면 start_end_pairs[future_index]의 start와 end에 새 경계를 써요. 그다음 future_index++로 개수를 하나 늘려요. 예시에서는 2번 칸에 쓴 뒤 개수가 3이 돼요.', '쓰는 순서도 중요해요. 이 코드에서는 먼저 현재 개수 위치에 두 경계를 쓰고 나중에 개수를 늘려요. 배열에는 128칸만 있으므로 유효한 용량 안에서 호출해야 해요. 경고가 배열을 자동으로 늘려 주지는 않아요.', '배열과 개수 변수에는 __initdata 표시가 있어요. 이 표시는 초기화 단계에 쓰는 데이터를 .init.data라는 영역에 배치하도록 해요. 영역은 실행 파일에서 같은 용도의 코드나 데이터를 모아 두는 구분이라고 생각하면 돼요.', '초기화용 영역은 초기화가 끝나면 회수될 수 있으므로 영구적으로 조회할 목록처럼 참조하면 안 돼요. 표시가 붙었다고 이 함수가 돌아가는 순간 바로 사라지는 것도 아니에요. 실제 회수는 커널의 초기화 완료 과정에서 처리하며, 단순한 전역 배열 학습 모형과 그 수명은 구별해야 해요.'], [('기존 항목과 병합에 성공한 경로에서도 future_index를 늘리나요?', ['네. 어떤 경로든 반드시 새 항목을 추가해요', '아니요. 기존 항목을 바꾼 뒤 돌아가요'], '정답은 두 번째예요. merged가 참이면 추가 코드 앞에서 return해요. 목록의 사용 개수는 그대로예요.'), ('__initdata는 이 목록이 어떤 용도의 데이터임을 표시하나요?', ['초기화 단계에서 사용하는 데이터예요', '일반 프로그램이 영구적으로 쓰는 메모리예요'], '정답은 첫 번째예요. 실제 정의는 .init.data 영역 배치 표시예요. 초기화가 끝난 뒤에도 영구 목록처럼 쓰겠다는 뜻은 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_458.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
